<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="page-heading"><div><p class="eyebrow">Access management</p><h1>Staff Accounts</h1></div><a class="button" href="<?= site_url('users/new') ?>">New Staff</a></div><div class="table-wrap"><table><thead><tr><th>Avatar</th><th>Username</th><th>Full Name</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><img class="avatar" src="<?= base_url($u['avatar']?'uploads/'.rawurlencode($u['avatar']):'images/avatar-placeholder.svg') ?>" alt=""></td><td><?= esc($u['username']) ?></td><td><?= esc($u['full_name']) ?></td><td><?= esc(date('M j, Y',strtotime($u['created_at']))) ?></td><td><div class="row-actions"><a class="text-link" href="<?= site_url('users/'.$u['id'].'/edit') ?>">Edit</a><form action="<?= site_url('users/'.$u['id'].'/delete') ?>" method="post" onsubmit="return confirm('Delete this staff account?')"><?= csrf_field() ?><button class="danger-link">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?= $this->endSection() ?>
